/**
 * `sitemap.xml`: the mur and every authored fiche, in both registres.
 *
 * Hand-written rather than generated by `@astrojs/sitemap`, because that plugin
 * sweeps every route the build emits — `/fiche-inconnue` and `/-/random`
 * included — and those must never be offered for indexing. The content
 * collection is the only source of truth here: a fiche exists in the sitemap
 * exactly when a Markdown file exists.
 *
 * URL shape: `build.format` is `directory`, so every page is one document per
 * directory and `Base.astro`'s canonical tag carries the trailing slash. The
 * sitemap repeats the canonical byte for byte. `astro.config.mjs` leaves
 * `trailingSlash` at its default, so the build emits directory URLs; the host
 * answers the unslashed form too (`cleanUrls: true` in `vercel.json`), so the
 * sitemap names the one form the canonical tag names. `lastmod` is omitted: the
 * content collection exposes no publication date, and a build timestamp would
 * claim the fiche changed every time the site is rebuilt.
 */
import type { APIRoute } from 'astro';
import { getCollection } from 'astro:content';

import { slugify } from '../lib/slug';

/** Fallback when `site` is not configured; keeps the endpoint self-contained. */
const DEFAULT_SITE = 'https://onditpas.fr';

/** Escape the five XML predefined entities, for slugs that carry punctuation. */
function escapeXml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

export const GET: APIRoute = async ({ site }) => {
  const base = site ?? new URL(DEFAULT_SITE);
  const fiches = await getCollection('fiches');

  const paths = ['/'];
  for (const fiche of fiches) {
    const slug = slugify(fiche.data.forme_fautive);
    paths.push(`/${slug}/`, `/${slug}/bordel/`);
  }

  const urls = paths
    .map((path) => `  <url>\n    <loc>${escapeXml(new URL(path, base).href)}</loc>\n  </url>`)
    .join('\n');

  const body = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls}
</urlset>
`;

  return new Response(body, {
    headers: { 'Content-Type': 'application/xml; charset=utf-8' },
  });
};
